import {money,today,addDays,month,uid,paid,balance,status,cash,recordPayment,billMonth,forecast,leakages,seed} from './engine.js';
const KEY='flowledger-nexus-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed();}catch{state=seed();}let page='Overview',horizon=30,query='',filter='All',scenario={days:30,delay:0,rate:100,extra:0},toastTimer;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',students:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7 M22 21v-2a4 4 0 0 0-3-3.9',invoice:'M6 3h12v18l-3-2-3 2-3-2-3 2z M9 7h6 M9 11h6 M9 15h3',wallet:'M3 6h17v15H3z M3 6V3h14v3 M16 11h5v5h-5z',chart:'M3 3v18h18 M6 15l4-5 4 3 6-8',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',expense:'M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',plus:'M12 5v14 M5 12h14',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',check:'m5 12 4 4L19 6',batch:'M3 8l9-5 9 5-9 5z M6 10v7l6 4 6-4v-7',menu:'M4 6h16 M4 12h16 M4 18h16',alert:'m12 3 10 18H2z M12 9v5 M12 17h.01'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-IN',{day:'numeric',month:'short'});
const initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
const student=id=>state.students.find(x=>x.id===id)||{name:'Archived student',parent:'',batch:''};
const outstanding=()=>state.invoices.reduce((a,i)=>a+balance(state,i),0);
const overdue=()=>state.invoices.filter(i=>status(state,i)==='Overdue');
const button=(label,action,cls='',id='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`;
const empty=t=>`<div class="empty">${t}</div>`;
function save(message){state.audit.unshift({id:uid(),text:message,time:new Date().toISOString()});try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Storage is full or unavailable. Export a backup before leaving.');return;}toast(message);render();}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
const navs=[['Overview','overview'],['Students','students'],['Batches','batch'],['Invoices','invoice'],['Payments','wallet'],['Expenses','expense'],['Decision Lab','chart'],['Rescue Planner','spark'],['Settings','settings']];
function render(){const fn={Overview:overview,Students:studentsPage,Batches:batchesPage,Invoices:invoicesPage,Payments:paymentsPage,Expenses:expensesPage,'Decision Lab':labPage,'Rescue Planner':rescuePage,Settings:settingsPage};app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">⌁</div><div>flowledger<small>N E X U S</small></div></div><div class="workspace">${esc(state.business)}<small>Tuition business workspace</small></div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navs.map(([n,i])=>`<button data-nav="${n}" class="${page===n?'active':''}" ${page===n?'aria-current="page"':''}>${icon(i)}${n}${n==='Rescue Planner'&&overdue().length?`<span class="badge">${overdue().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-note"><strong>Your business, in focus.</strong>Records are saved in this browser. Export a backup anytime.</div><div class="profile"><div class="avatar">BM</div><div style="font-size:13px">Business owner<small>Personal workspace</small></div></div></div></aside><div class="content"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb">Workspace <span style="margin:0 12px;color:#b4bfc6">/</span> <strong>${page}</strong></div><div class="top-actions"><button class="search-button" data-action="search" aria-label="Search workspace">${icon('search')}<span>Search your workspace</span><kbd>Ctrl K</kbd></button><span class="demo-pill">${state.demo?'Demo workspace':'Local workspace'}</span><div class="avatar">BM</div></div></header><main id="main" class="main">${fn[page]()}<footer class="footer"><span>FlowLedger Nexus · Clarity for your next decision.</span><span>INR · India time · ${state.demo?'Illustrative sample data':'Browser-local records'}</span></footer></main></div></div>`;}
function heading(title,sub,actions='',eyebrow='BUSINESS COMMAND CENTER'){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`;}
function stat(label,value,note,ic='wallet',good=false){return `<div class="stat"><div class="stat-top">${label}${icon(ic)}</div><div class="stat-value">${value}</div><div class="stat-note ${good?'good':''}">${note}</div></div>`;}
function chart(base,alt){const w=660,h=235,p={l:55,r:15,t:18,b:34};const vals=[...base,...(alt||[])].map(x=>x.value);let low=Math.min(0,...vals,state.reserve),high=Math.max(...vals,state.reserve,1);high+=Math.max(1000,(high-low)*.12);const x=i=>p.l+i/(base.length-1)*(w-p.l-p.r),y=v=>h-p.b-(v-low)/(high-low)*(h-p.t-p.b);const line=a=>a.map((v,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(v.value).toFixed(1)}`).join(' ');const min=base.reduce((a,b)=>a.value<b.value?a:b);return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Daily forecast. Minimum baseline cash ${money(min.value)} on ${fmt(min.date)}. ${alt?'Dashed line shows the scenario.':''}"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#53b59e" stop-opacity=".24"/><stop offset="1" stop-color="#53b59e" stop-opacity=".01"/></linearGradient></defs>${Array.from({length:5},(_,i)=>{const v=low+(high-low)*i/4;return `<line x1="${p.l}" x2="${w-p.r}" y1="${y(v)}" y2="${y(v)}" stroke="#eaf0f2" stroke-dasharray="3 4"/><text x="${p.l-10}" y="${y(v)+4}" text-anchor="end">${v<0?'−':''}₹${Math.round(Math.abs(v)/1000)}k</text>`;}).join('')}<path d="${line(base)} L${x(base.length-1)},${h-p.b} L${p.l},${h-p.b}Z" fill="url(#chartFill)"/><line x1="${p.l}" x2="${w-p.r}" y1="${y(state.reserve)}" y2="${y(state.reserve)}" stroke="#c3a37c" stroke-dasharray="4 5"/><path d="${line(base)}" fill="none" stroke="#148778" stroke-width="2.8" stroke-linejoin="round"/>${alt?`<path d="${line(alt)}" fill="none" stroke="#ba8150" stroke-width="2.3" stroke-dasharray="6 4"/>`:''}${[0,Math.floor((base.length-1)/4),Math.floor((base.length-1)/2),Math.floor((base.length-1)*3/4),base.length-1].map(i=>`<text x="${x(i)}" y="${h-8}" text-anchor="middle">${fmt(base[i].date)}</text>`).join('')}</svg>`;}
function forecastCard(){const f=forecast(state,{days:horizon}),min=f.reduce((a,b)=>a.value<b.value?a:b),breach=f.find(x=>x.value<state.reserve);return `<section class="card"><div class="card-head"><div><h2>Cash flow outlook</h2><p>A clearer view of the days ahead</p></div><div class="segmented">${[30,60,90].map(n=>`<button data-horizon="${n}" class="${horizon===n?'active':''}">${n} days</button>`).join('')}</div></div><div class="card-body"><div class="chart-legend"><span><i class="legend-line"></i>Expected cash</span><span><i class="legend-line amber"></i>Reserve target</span></div>${chart(f)}<div class="chart-summary"><div>Lowest projected balance<strong class="${min.value<state.reserve?'risk':''}">${money(min.value)} <span style="font-size:12px;font-weight:400">on ${fmt(min.date)}</span></strong></div><div>Closing balance<strong>${money(f.at(-1).value)}</strong></div><div>Reserve outlook<strong class="${breach?'risk':''}">${breach?'Below target '+fmt(breach.date):'Above target'}</strong></div></div></div></section>`;}
function invoiceTable(list,compact=false){if(!list.length)return empty('No invoices found. Create an invoice to get started.');return `<div class="table-wrap"><table><thead><tr><th>Student / invoice</th>${!compact?'<th>Due date</th>':''}<th>Outstanding</th><th>Status</th><th></th></tr></thead><tbody>${list.map(i=>{const st=student(i.studentId),s=status(state,i);return `<tr><td><div class="person"><div class="avatar">${esc(initials(st.name))}</div><div><strong>${esc(st.name)}</strong><small>${esc(i.period)} · ${esc(st.batch.split(' · ')[0])}</small></div></div></td>${!compact?`<td>${fmt(i.due)}</td>`:''}<td class="numeric">${money(balance(state,i))}</td><td><span class="status ${s.toLowerCase()}">${s}</span></td><td><button class="text-btn" data-action="invoice-detail" data-id="${esc(i.id)}">View</button></td></tr>`;}).join('')}</tbody></table></div>`;}
function expenseList(list){return list.length?list.map(e=>`<div class="expense-line"><div class="date-box"><small>${new Date(e.due+'T12:00:00Z').toLocaleDateString('en',{month:'short'})}</small>${Number(e.due.slice(-2))}</div><div><strong>${esc(e.title)}</strong><small>${esc(e.category)}</small></div><div class="amount"><strong>${money(e.amount)}</strong><small>${e.paid?'Paid':e.due<today()?'Overdue':'Scheduled'}</small></div></div>`).join(''):empty('No upcoming expenses.');}
function overview(){const late=overdue(),missing=leakages(state),f=forecast(state),risk=f.find(x=>x.value<state.reserve),expenses=state.expenses.filter(e=>!e.paid).sort((a,b)=>a.due.localeCompare(b.due));return heading('Your business, at a glance.','A little clarity today. Better decisions tomorrow.',button(icon('download')+' Export','export')+button(icon('plus')+' Create invoice','new-invoice','primary'))+`<div class="brief"><div class="brief-icon">${icon('spark')}</div><div><h3>${risk?'A little attention now goes a long way.':'You’re ready for the days ahead.'}</h3><p>${late.length} overdue invoices need a follow-up. ${missing.length?`${missing.length} student${missing.length===1?'': 's'} ${missing.length===1?'is':'are'} missing this month’s invoice.`:'Monthly billing is up to date.'} ${risk?`Cash may fall below your reserve on ${fmt(risk.date)}.`:''}</p></div>${button('Review action plan','rescue','small')}</div><div class="stats">${stat('Cash available',money(cash(state)),'Opening cash + recorded transactions','wallet',true)}${stat('Outstanding fees',money(outstanding()),`${late.length} overdue · ${state.invoices.filter(i=>balance(state,i)>0).length} unpaid invoices`,'invoice')}${stat('Expected collections',money(f.at(-1).value-cash(state)+expenses.filter(e=>e.due<=addDays(today(),30)).reduce((a,e)=>a+e.amount,0)),'Next 30 days · assumption-based','chart',true)}${stat('Upcoming expenses',money(expenses.filter(e=>e.due<=addDays(today(),30)).reduce((a,e)=>a+e.amount,0)),'Scheduled in the next 30 days','expense')}</div><div class="grid">${forecastCard()}<section class="card"><div class="card-head"><div><h2>Your next best moves</h2><p>Small actions. Meaningful impact.</p></div>${icon('spark')}</div><div class="card-body"><div class="task"><div class="task-icon">${icon('clock')}</div><div><h3>Follow up on overdue fees</h3><p>${money(late.reduce((a,i)=>a+balance(state,i),0))} across ${late.length} invoices is awaiting collection.</p><button class="text-btn" data-action="overdue">Review overdue invoices</button></div></div><div class="task"><div class="task-icon teal">${icon('invoice')}</div><div><h3>${missing.length?'Close a billing gap':'Monthly billing is complete'}</h3><p>${missing.length?`${missing.length} active student missing an invoice. Potential billing: ${money(missing.reduce((a,s)=>a+s.fee,0))}.`:'Every active student has an invoice for this month.'}</p><button class="text-btn" data-action="billing">Review monthly billing</button></div></div><div class="task"><div class="task-icon teal">${icon('chart')}</div><div><h3>Plan for a slower collection week</h3><p>See how payment delays affect your cash reserve.</p><button class="text-btn" data-action="lab">Explore Decision Lab</button></div></div></div><div class="task-footer">Calculated from your invoices, commitments, and bills.</div></section></div><div class="grid"><section class="card"><div class="card-head"><div><h2>Collections to keep an eye on</h2><p>Outstanding invoices, ordered by due date</p></div><button class="text-btn" data-nav="Invoices">View all</button></div>${invoiceTable(state.invoices.filter(i=>balance(state,i)>0).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,4),true)}</section><section class="card"><div class="card-head"><div><h2>Coming up</h2><p>Your next scheduled expenses</p></div><button class="text-btn" data-nav="Expenses">View all</button></div><div class="card-body">${expenseList(expenses.slice(0,4))}</div></section></div>`;}
function studentsPage(){const list=state.students.filter(s=>!s.archived&&`${s.name} ${s.parent} ${s.batch}`.toLowerCase().includes(query.toLowerCase()));return heading('People behind the progress.','Manage students, parent contacts, and monthly fee plans.',button('Generate monthly fees','billing')+button(icon('plus')+' Add student','new-student','primary'),'STUDENTS & FAMILIES')+`<div class="toolbar"><input aria-label="Search students" id="list-search" placeholder="Search students, parents, batches…" value="${esc(query)}"><span class="pill">${list.length} active students</span></div><div class="card">${list.length?`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Parent</th><th>Batch</th><th>Monthly fee</th><th>Balance</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td><div class="person"><div class="avatar">${esc(initials(s.name))}</div><strong>${esc(s.name)}</strong></div></td><td>${esc(s.parent)}<br><small style="color:var(--muted)">${esc(s.phone||'No phone added')}</small></td><td>${esc(s.batch)}</td><td class="numeric">${money(s.fee)}</td><td>${money(state.invoices.filter(i=>i.studentId===s.id).reduce((a,i)=>a+balance(state,i),0))}</td><td><button class="text-btn" data-action="edit-student" data-id="${s.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>`:empty('No students match your search.')}</div>`;}
function batchesPage(){const groups=[...new Set(state.students.filter(s=>!s.archived).map(s=>s.batch))];return heading('Room to grow.','Understand enrollment and model the economics of your next batch.',button(icon('plus')+' Add student','new-student','primary'),'BATCH INTELLIGENCE')+`<div class="batch-grid">${groups.map((name,n)=>{const list=state.students.filter(s=>!s.archived&&s.batch===name),revenue=list.reduce((a,s)=>a+s.fee,0);return `<section class="card batch-card"><div class="batch-mark">${icon('batch')}</div><h2>${esc(name)}</h2><p class="subtitle">Monthly fee plan</p><dl><div><dt>Enrolled students</dt><dd>${list.length}</dd></div><div><dt>Monthly billed potential</dt><dd>${money(revenue)}</dd></div></dl><div class="progress"><span style="width:100%"></span></div><div style="margin-top:20px">${button('Model batch costs','profit','small',name)}</div></section>`;}).join('')||empty('Add a student with a batch name to create your first batch.')}</div><div class="notice" style="margin-top:24px">Monthly potential assumes all active students are billed at their saved fee. It is not collected revenue. Use the cost model to estimate contribution and break-even enrollment.</div>`;}
function invoicesPage(){let list=state.invoices.filter(i=>`${student(i.studentId).name} ${i.period}`.toLowerCase().includes(query.toLowerCase())&&(filter==='All'||status(state,i)===filter)).sort((a,b)=>a.due.localeCompare(b.due));return heading('Every fee, accounted for.','Create invoices, track balances, and follow up with confidence.',button('Monthly billing','billing')+button(icon('plus')+' Create invoice','new-invoice','primary'),'BILLING & COLLECTIONS')+`<div class="toolbar"><input id="list-search" aria-label="Search invoices" value="${esc(query)}" placeholder="Search student or billing month…"><select id="status-filter" aria-label="Filter by payment status">${['All','Overdue','Partial','Unpaid','Paid'].map(s=>`<option ${s===filter?'selected':''}>${s}</option>`).join('')}</select><span class="pill">${list.length} invoices</span></div><section class="card">${invoiceTable(list)}</section>`;}
function paymentsPage(){return heading('Collections, confirmed.','Every recorded payment updates its invoice and your available cash.',button('Record a payment','payment-picker','primary'),'PAYMENT LEDGER')+`<div class="stats">${stat('Recorded collections',money(state.payments.reduce((a,p)=>a+p.amount,0)),`${state.payments.length} payment entries`)}${stat('Outstanding',money(outstanding()),'Remaining invoice balances','invoice')}${stat('Payment commitments',money(state.promises.reduce((a,p)=>a+Math.min(p.amount,balance(state,state.invoices.find(i=>i.id===p.invoiceId))),0)),'Promises are not confirmed cash','clock')}${stat('Cash available',money(cash(state)),'Including opening balance','wallet')}</div><section class="card"><div class="card-head"><h2>Payment history</h2>${button('Export CSV','payments-csv','small')}</div>${state.payments.length?`<div class="table-wrap"><table><thead><tr><th>Student</th><th>Date</th><th>Method</th><th>Amount</th><th></th></tr></thead><tbody>${[...state.payments].sort((a,b)=>b.date.localeCompare(a.date)).map(p=>{const i=state.invoices.find(i=>i.id===p.invoiceId);return `<tr><td>${esc(student(i.studentId).name)}</td><td>${fmt(p.date)}</td><td>${esc(p.method)}</td><td class="numeric">${money(p.amount)}</td><td><button class="text-btn" data-action="receipt" data-id="${p.id}">Receipt</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('No payments recorded yet.')}</section>`;}
function expensesPage(){return heading('Stay ahead of your bills.','Scheduled expenses feed directly into your cash forecast.',button(icon('plus')+' Add expense','new-expense','primary'),'EXPENSE MANAGEMENT')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Expense</th><th>Category</th><th>Due</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody>${[...state.expenses].sort((a,b)=>a.due.localeCompare(b.due)).map(e=>`<tr><td><strong>${esc(e.title)}</strong></td><td>${esc(e.category)}</td><td>${fmt(e.due)}</td><td class="numeric">${money(e.amount)}</td><td><span class="status ${e.paid?'paid':e.due<today()?'overdue':''}">${e.paid?'Paid':e.due<today()?'Overdue':'Scheduled'}</span></td><td>${e.paid?'':button('Mark paid','pay-expense','small',e.id)}</td></tr>`).join('')}</tbody></table></div>${!state.expenses.length?empty('No expenses yet. Add rent, salaries, or supplies.'):''}</section>`;}
function labPage(){const base=forecast(state,{days:scenario.days}),sim=forecast(state,scenario),min=sim.reduce((a,b)=>a.value<b.value?a:b),breach=sim.find(x=>x.value<state.reserve);return heading('Make the next move with clarity.','Test payment delays and new costs before they affect your business.',button('Save scenario','save-scenario')+button('Reset assumptions','reset-scenario'),'DECISION LAB')+`<div class="grid" style="grid-template-columns:minmax(260px,.8fr) minmax(0,1.8fr)"><section class="card"><div class="card-head"><h2>What changes?</h2>${icon('settings')}</div><div class="controls"><div class="field"><label for="days">Forecast window</label><select id="days" data-scenario="days">${[30,60,90].map(n=>`<option value="${n}" ${scenario.days===n?'selected':''}>${n} days</option>`).join('')}</select></div><div class="field"><div class="range-title"><label for="delay">Collection delay</label><span>${scenario.delay} days</span></div><input id="delay" type="range" min="0" max="30" step="1" value="${scenario.delay}" data-scenario="delay"><small>Moves all expected collections and commitments later.</small></div><div class="field"><div class="range-title"><label for="rate">Collection rate</label><span>${scenario.rate}%</span></div><input id="rate" type="range" min="0" max="100" step="5" value="${scenario.rate}" data-scenario="rate"><small>Share of the current outstanding fees assumed to arrive.</small></div><div class="field"><label for="extra">Additional expense (₹)</label><input id="extra" type="number" min="0" max="10000000" step="1" value="${scenario.extra}" data-scenario="extra"><small>One-time cost, seven days from today.</small></div><div class="notice">This is a simulation. Your invoices, payments, and expenses stay unchanged.</div></div></section><div><div class="metric-row">${stat('Lowest scenario cash',money(min.value),fmt(min.date),'wallet')}${stat('Reserve gap',money(Math.max(0,state.reserve-min.value)),'Against your saved target','alert')}${stat('First reserve breach',breach?fmt(breach.date):'None','Within selected window','clock')}</div><section class="card"><div class="card-head"><div><h2>Two paths. One clear picture.</h2><p>Baseline and your edited scenario</p></div></div><div class="card-body"><div class="chart-legend"><span><i class="legend-line"></i>Baseline</span><span><i class="legend-line amber"></i>Your scenario</span></div>${chart(base,sim)}<div class="chart-summary"><div>Baseline closing cash<strong>${money(base.at(-1).value)}</strong></div><div>Scenario closing cash<strong>${money(sim.at(-1).value)}</strong></div><div>Difference<strong>${money(sim.at(-1).value-base.at(-1).value)}</strong></div></div></div></section></div></div><div class="notice"><strong>Forecast assumptions:</strong> Only saved invoices and expenses are included; future monthly bills are not generated implicitly. Current overdue fees are assumed to arrive in seven days unless covered by a future commitment. Uncovered future fees arrive on their due date. Overdue expenses fall today. A promise changes timing, not the invoice balance. No predicted collection is guaranteed.</div><section class="card" style="margin-top:22px"><div class="card-head"><h2>Saved scenarios</h2></div><div class="card-body">${state.scenarios.length?state.scenarios.map(s=>`<div class="expense-line"><div><strong>${esc(s.name)}</strong><small>${s.delay}-day delay · ${s.rate}% collections · ${money(s.extra)} extra cost</small></div><div class="amount">${button('Load','load-scenario','small',s.id)}</div></div>`).join(''):empty('Save a scenario to revisit its assumptions later.')}</div></section>`;}
function rescuePage(){const f=forecast(state),min=f.reduce((a,b)=>a.value<b.value?a:b),missing=leakages(state),list=overdue().sort((a,b)=>a.due.localeCompare(b.due)||balance(state,b)-balance(state,a));return heading('Turn attention into action.','A practical collection queue, with the evidence behind every task.',button('Explore forecast','lab'),'RESCUE PLANNER')+`<div class="brief"><div class="brief-icon">${icon('alert')}</div><div><h3>${min.value<state.reserve?`${money(state.reserve-min.value)} below your reserve at the lowest point.`:'Your projected cash stays above the reserve target.'}</h3><p>Lowest baseline balance: ${money(min.value)} on ${fmt(min.date)}. Priorities below are ordered by overdue date, then outstanding amount.</p></div></div>${missing.length?`<section class="card rescue-card"><div class="rescue-number">${icon('invoice')}</div><div class="details"><h2>Close the monthly billing gap</h2><p>${missing.map(s=>esc(s.name)).join(', ')} ${missing.length===1?'has':'have'} no invoice for ${month(today())}. Review before generating.</p>${button('Review missing invoices','billing','small')}</div><div class="impact">${money(missing.reduce((a,s)=>a+s.fee,0))}<small>Potential billing · not cash</small></div></section>`:''}${list.map((i,n)=>{const st=student(i.studentId),prom=state.promises.filter(p=>p.invoiceId===i.id);return `<section class="card rescue-card"><div class="rescue-number">${n+1}</div><div class="details"><h2>Follow up with ${esc(st.parent)}</h2><p>${esc(st.name)} · ${esc(i.period)} fee · due ${fmt(i.due)}.<br>${prom.length?`Saved commitment: ${money(prom[0].amount)} on ${fmt(prom[0].date)}. ${prom[0].date<today()?'The commitment date has passed.':''}`:'No payment commitment is saved.'}</p><div class="actions">${button('Draft reminder','reminder','small',i.id)}${button('Save commitment','promise','small',i.id)}${button('View evidence','invoice-detail','small',i.id)}</div></div><div class="impact">${money(balance(state,i))}<small>Outstanding · not guaranteed</small></div></section>`;}).join('')||empty('No overdue invoices. You’re up to date.')}<div class="notice">These are rule-based suggestions, not AI predictions. Collecting an invoice already included in the baseline does not add it a second time. Record a payment only after confirming receipt.</div>`;}
function settingsPage(){return heading('A workspace that fits your business.','Manage your opening balance, reserve target, and local backups.','','WORKSPACE SETTINGS')+`<div class="settings-grid"><section class="card"><h2>Business preferences</h2><form id="settings-form" class="form"><div class="field"><label for="business">Business name</label><input id="business" name="business" value="${esc(state.business)}" required maxlength="70"></div><div class="form-row"><div class="field"><label for="opening">Opening balance (₹)</label><input id="opening" name="opening" type="number" value="${state.opening}" required step="1"></div><div class="field"><label for="reserve">Reserve target (₹)</label><input id="reserve" name="reserve" type="number" value="${state.reserve}" min="0" required step="1"></div></div><p class="subtitle">Opening balance excludes the payment and paid-expense records entered here.</p><button class="btn primary" type="submit">Save preferences</button></form></section><section class="card"><h2>Your data, your control</h2><p class="subtitle">This version stores records in this browser. It does not sync between devices or provide staff logins.</p><div class="actions" style="margin:20px 0">${button('Export backup','export')}${button('Restore backup','import')}</div><input id="backup-file" type="file" accept="application/json,.json" hidden><div class="notice">Keep a backup before clearing browser data. Restore replaces this workspace after confirmation.</div><div class="actions" style="margin-top:20px">${button('Start empty workspace','clear','danger small')}${button('Reload sample data','reset-demo','small')}</div></section><section class="card" style="grid-column:1/-1"><h2>Activity history</h2><p class="subtitle">Local change log · latest 30 actions</p>${state.audit.length?state.audit.slice(0,30).map(a=>`<div class="audit-item">${esc(a.text)}<small>${new Date(a.time).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})} IST</small></div>`).join(''):empty('Your changes will appear here.')}</section></div>`;}
function openModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${body}`;if(!modal.open)modal.showModal();}
function field(label,name,type='text',value='',attrs=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function form(body,submit='Save',id='modal-form'){return `<form class="form" id="${id}">${body}<div class="error" id="form-error" role="alert"></div><div class="form-actions">${button('Cancel','close')}<button type="submit" class="btn primary">${submit}</button></div></form>`;}
function bindForm(fn){document.querySelector('#modal-form').onsubmit=e=>{e.preventDefault();try{fn(Object.fromEntries(new FormData(e.target)));}catch(err){document.querySelector('#form-error').textContent=err.message;}};}
function studentForm(id){const s=state.students.find(x=>x.id===id);openModal(s?'Edit student':'Add a student',form(field('Student name','name','text',s?.name||'','required maxlength="80"')+field('Parent / guardian','parent','text',s?.parent||'','required maxlength="80"')+field('Phone (optional)','phone','tel',s?.phone||'','maxlength="20"')+field('Batch name','batch','text',s?.batch||'','required maxlength="80" list="batch-options"')+`<datalist id="batch-options">${[...new Set(state.students.map(s=>s.batch))].map(b=>`<option value="${esc(b)}">`).join('')}</datalist>`+field('Monthly fee (₹)','fee','number',s?.fee||3000,'required min="1" max="1000000" step="1"')+(s?button('Archive student','archive-student','danger small',id):''),'Save student'));bindForm(d=>{for(const k of ['name','parent','batch'])if(!d[k].trim())throw Error('Name, parent, and batch must not be blank.');const values={...d,name:d.name.trim(),parent:d.parent.trim(),batch:d.batch.trim(),fee:Number(d.fee)};if(s)Object.assign(s,values);else state.students.push({...values,id:uid(),archived:false});modal.close();save(s?'Student updated':'Student added');});}
function invoiceForm(){const list=state.students.filter(s=>!s.archived);if(!list.length){toast('Add a student first.');studentForm();return;}openModal('Create an invoice',form(`<div class="field"><label for="f-studentId">Student</label><select id="f-studentId" name="studentId">${list.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div>`+field('Billing month','period','month',month(today()),'required')+field('Amount (₹)','amount','number',list[0].fee,'required min="1" max="1000000" step="1"')+field('Due date','due','date',addDays(today(),7),'required'),'Create invoice'));document.querySelector('#f-studentId').onchange=e=>document.querySelector('#f-amount').value=student(e.target.value).fee;bindForm(d=>{if(state.invoices.some(i=>i.studentId===d.studentId&&i.period===d.period))throw Error('This student already has an invoice for that billing month.');state.invoices.push({...d,amount:Number(d.amount),id:uid(),created:today()});modal.close();save('Invoice created');});}
function billingForm(){openModal('Generate monthly fees',form(field('Billing month','period','month',month(today()),'required')+`<div class="notice">Creates one invoice for each active student missing that month’s invoice, using their saved monthly fee. Existing invoices are skipped. Due date is the fifth of the selected month.</div>`,'Generate invoices'));bindForm(d=>{const count=billMonth(state,d.period);modal.close();save(`${count} monthly invoice${count===1?'':'s'} generated`);});}
function invoiceDetail(id){const i=state.invoices.find(i=>i.id===id),s=student(i.studentId),ps=state.payments.filter(p=>p.invoiceId===id);openModal('Invoice details',`<div class="receipt"><div class="eyebrow">${esc(state.business)}</div><h2>${esc(s.name)}</h2><p>${esc(s.parent)} · ${esc(s.batch)}</p><span class="status ${status(state,i).toLowerCase()}">${status(state,i)}</span><div class="total">${money(balance(state,i))}</div><p>Outstanding · Invoice total ${money(i.amount)}<br>Billing month: ${esc(i.period)} · Due: ${fmt(i.due)}<br><small>Reference: ${esc(i.id)}</small></p><hr><h3>Payment history</h3>${ps.length?ps.map(p=>`<p>${fmt(p.date)} · ${esc(p.method)} <strong style="float:right">${money(p.amount)}</strong></p>`).join(''):'<p>No confirmed payments yet.</p>'}<div class="form-actions" style="flex-wrap:wrap">${button('Print / PDF','print')}${balance(state,i)>0?button('Reminder','reminder','',id)+button('Record payment','payment','primary',id):''}</div></div>`);}
function paymentForm(id){const i=state.invoices.find(i=>i.id===id);openModal('Record a confirmed payment',form(`<div class="notice">${esc(student(i.studentId).name)} · Outstanding <strong>${money(balance(state,i))}</strong></div>`+field('Amount received (₹)','amount','number',balance(state,i),`required min="1" max="${balance(state,i)}" step="1"`)+field('Payment date','date','date',today(),`required max="${today()}"`)+`<div class="field"><label for="f-method">Method</label><select name="method" id="f-method"><option>UPI</option><option>Bank transfer</option><option>Cash</option><option>Card</option></select></div>`,'Confirm payment'));bindForm(d=>{recordPayment(state,id,Number(d.amount),d.date,d.method);modal.close();save('Payment recorded and invoice updated');});}
function promiseForm(id){const i=state.invoices.find(i=>i.id===id),p=state.promises.find(p=>p.invoiceId===id);openModal('Save a payment commitment',form(`<div class="notice">${esc(student(i.studentId).parent)} · Replaces any previous commitment for this invoice. A commitment is not a payment.</div>`+field('Promised amount (₹)','amount','number',p?.amount||balance(state,i),`required min="1" max="${balance(state,i)}" step="1"`)+field('Promised date','date','date',p?.date>=today()?p.date:addDays(today(),3),`required min="${today()}"`),'Save commitment'));bindForm(d=>{state.promises=state.promises.filter(p=>p.invoiceId!==id);state.promises.push({id:uid(),invoiceId:id,amount:Number(d.amount),date:d.date});modal.close();save('Payment commitment saved');});}
function reminder(id){const i=state.invoices.find(i=>i.id===id),s=student(i.studentId);const message=`Hello ${s.parent}, a friendly reminder that ${money(balance(state,i))} remains outstanding for ${s.name}'s tuition fee for ${i.period}, due on ${fmt(i.due)}. Please let us know your expected payment date. Thank you, ${state.business}.`;openModal('Review your reminder',`<div class="form"><div class="notice">Template draft using the saved invoice balance. Review before copying or sharing. Nothing is sent automatically.</div><div class="field"><label for="reminder-text">Message</label><textarea id="reminder-text" rows="7">${esc(message)}</textarea></div><div class="actions">${button('Copy message','copy-reminder','primary')}${button('Save commitment','promise','',id)}</div></div>`);}
function expenseForm(){openModal('Add an expense',form(field('Expense name','title','text','','required maxlength="100"')+`<div class="field"><label for="f-category">Category</label><select id="f-category" name="category"><option>Rent</option><option>Salaries</option><option>Supplies</option><option>Utilities</option><option>Other</option></select></div>`+field('Amount (₹)','amount','number','','required min="1" max="10000000" step="1"')+field('Due date','due','date',addDays(today(),7),'required'),'Save expense'));bindForm(d=>{if(!d.title.trim())throw Error('Enter an expense name.');state.expenses.push({...d,amount:Number(d.amount),id:uid(),paid:false});modal.close();save('Expense added to forecast');});}
function receipt(id){const p=state.payments.find(p=>p.id===id),i=state.invoices.find(i=>i.id===p.invoiceId),s=student(i.studentId);openModal('Payment receipt',`<div class="receipt"><div class="eyebrow">PAYMENT RECEIPT</div><h2>${esc(state.business)}</h2><div class="total">${money(p.amount)}</div><span class="status paid">Payment recorded</span><hr><p><strong>Student:</strong> ${esc(s.name)}<br><strong>Parent:</strong> ${esc(s.parent)}<br><strong>Date:</strong> ${fmt(p.date)}<br><strong>Method:</strong> ${esc(p.method)}<br><strong>Billing month:</strong> ${esc(i.period)}<br><strong>Receipt:</strong> ${esc(p.id)}</p><p>Remaining invoice balance: ${money(balance(state,i))}</p><div class="form-actions">${button('Print / Save PDF','print','primary')}</div></div>`);}
function profit(name){const list=state.students.filter(s=>!s.archived&&s.batch===name),average=Math.round(list.reduce((a,s)=>a+s.fee,0)/list.length);openModal('Batch break-even model',`<div class="form"><h3>${esc(name)}</h3>${field('Students','count','number',list.length,'min="0" max="1000"')}${field('Average monthly fee (₹)','fee','number',average,'min="1" max="1000000"')}${field('Monthly fixed costs (₹)','fixed','number',10000,'min="0" max="10000000"')}${field('Variable cost per student (₹)','variable','number',300,'min="0" max="1000000"')}<div id="profit-result" class="notice"></div><small style="color:var(--muted)">Illustrative costs. Replace them with teaching, room, and material costs for this batch. Shared costs require your allocation.</small></div>`);const calc=()=>{const value=n=>Number(document.querySelector('#f-'+n).value);const count=value('count'),fee=value('fee'),fixed=value('fixed'),variable=value('variable'),unit=fee-variable;document.querySelector('#profit-result').innerHTML=`Monthly contribution: <strong>${money(count*unit-fixed)}</strong><br>Break-even enrollment: <strong>${unit>0?Math.ceil(fixed/unit)+' students':'Not achievable at these fees and costs'}</strong>`;};modal.querySelectorAll('input').forEach(i=>i.oninput=calc);calc();}
function download(name,data,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function confirmAction(title,text,fn){openModal(title,form(`<p>${text}</p>`,'Confirm'));bindForm(()=>{modal.close();fn();});}
function searchModal(){openModal('Find anything',`<div class="form"><input id="global-search" aria-label="Search workspace" placeholder="Type a student, parent, or expense…"><div class="search-results" id="search-results"></div></div>`);const input=document.querySelector('#global-search');input.oninput=()=>{const q=input.value.toLowerCase().trim(),results=document.querySelector('#search-results');if(!q){results.innerHTML='';return;}results.innerHTML=state.students.filter(s=>`${s.name} ${s.parent}`.toLowerCase().includes(q)).slice(0,8).map(s=>`<button data-action="edit-student" data-id="${s.id}">${esc(s.name)} <span class="pill">Student</span></button>`).join('')+state.invoices.filter(i=>`${student(i.studentId).name} ${i.period}`.toLowerCase().includes(q)).slice(0,8).map(i=>`<button data-action="invoice-detail" data-id="${i.id}">${esc(student(i.studentId).name)} · ${esc(i.period)} <span class="pill">Invoice</span></button>`).join('')+state.expenses.filter(e=>e.title.toLowerCase().includes(q)).slice(0,5).map(e=>`<button data-nav="Expenses">${esc(e.title)} · ${money(e.amount)} <span class="pill">Expense</span></button>`).join('')||'<p>No matching records.</p>';};}
function go(n){page=n;query='';filter='All';modal.close();render();window.scrollTo(0,0);}
document.addEventListener('click',async e=>{const n=e.target.closest('[data-nav]');if(n){go(n.dataset.nav);return;}const h=e.target.closest('[data-horizon]');if(h){horizon=Number(h.dataset.horizon);render();return;}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
switch(a){case'menu':document.querySelector('.sidebar').classList.toggle('open');break;case'close':modal.close();break;case'new-student':studentForm();break;case'edit-student':studentForm(id);break;case'new-invoice':invoiceForm();break;case'billing':billingForm();break;case'invoice-detail':invoiceDetail(id);break;case'payment':paymentForm(id);break;case'promise':promiseForm(id);break;case'reminder':reminder(id);break;case'new-expense':expenseForm();break;case'receipt':receipt(id);break;case'profit':profit(id);break;case'print':window.print();break;case'lab':go('Decision Lab');break;case'rescue':go('Rescue Planner');break;case'overdue':page='Invoices';filter='Overdue';query='';render();break;case'search':searchModal();break;
case'payment-picker':{const list=state.invoices.filter(i=>balance(state,i)>0);openModal('Choose an invoice',`<div class="form">${list.map(i=>button(`${esc(student(i.studentId).name)} · ${money(balance(state,i))}`,'payment','',i.id)).join('')||empty('All invoices are paid.')}</div>`);break;}
case'archive-student':confirmAction('Archive student?','Existing invoices and payments will be retained. This student will be excluded from future monthly billing.',()=>{student(id).archived=true;save('Student archived');});break;
case'pay-expense':{const ex=state.expenses.find(x=>x.id===id);confirmAction('Confirm expense payment',`Record ${money(ex.amount)} paid for ${esc(ex.title)}? This reduces available cash.`,()=>{if(ex.paid)return;ex.paid=true;ex.paidDate=today();save('Expense marked paid');});break;}
case'copy-reminder':try{await navigator.clipboard.writeText(document.querySelector('#reminder-text').value);toast('Reminder copied. Review it before sending.');}catch{document.querySelector('#reminder-text').select();toast('Select and copy the message using Ctrl+C.');}break;
case'export':download(`flowledger-backup-${today()}.json`,JSON.stringify(state,null,2));toast('Backup exported');break;
case'payments-csv':{const cell=v=>'"'+String(v).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const rows=[['Student','Date','Amount','Method','Reference'],...state.payments.map(p=>[student(state.invoices.find(i=>i.id===p.invoiceId).studentId).name,p.date,p.amount,p.method,p.id])];download('flowledger-payments.csv',rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv');break;}
case'reset-scenario':scenario={days:30,delay:0,rate:100,extra:0};render();break;
case'save-scenario':openModal('Save scenario',form(field('Scenario name','name','text','','required maxlength="80"'),'Save scenario'));bindForm(d=>{if(!d.name.trim())throw Error('Enter a scenario name.');state.scenarios.push({...scenario,name:d.name.trim(),id:uid()});modal.close();save('Scenario assumptions saved');});break;
case'load-scenario':{const s=state.scenarios.find(s=>s.id===id);scenario={days:s.days,delay:s.delay,rate:s.rate,extra:s.extra};render();toast('Saved assumptions loaded using current records');break;}
case'import':document.querySelector('#backup-file').click();break;
case'clear':confirmAction('Start an empty workspace?','This replaces all records in this browser. Export a backup first if you need the current data.',()=>{state={...seed(),demo:false,opening:0,students:[],invoices:[],payments:[],expenses:[],promises:[],scenarios:[],audit:[]};save('Empty workspace created');});break;
case'reset-demo':confirmAction('Reload sample data?','This replaces the current workspace with illustrative sample records. Export a backup first to keep your changes.',()=>{state=seed();save('Sample workspace loaded');});break;
}});
document.addEventListener('input',e=>{if(e.target.id==='list-search'){const pos=e.target.selectionStart;query=e.target.value;render();const el=document.querySelector('#list-search');el.focus();el.setSelectionRange(pos,pos);}});
document.addEventListener('change',async e=>{if(e.target.id==='status-filter'){filter=e.target.value;render();}if(e.target.dataset.scenario){const name=e.target.dataset.scenario,n=Number(e.target.value);if(!e.target.checkValidity()||!Number.isFinite(n))return;scenario[name]=n;render();document.querySelector(`[data-scenario="${name}"]`)?.focus();}if(e.target.id==='backup-file'&&e.target.files[0]){try{if(e.target.files[0].size>5e6)throw Error('Backup is too large (maximum 5 MB).');const data=JSON.parse(await e.target.files[0].text());validateBackup(data);confirmAction('Restore this backup?',`Replace current records with ${data.students.length} students and ${data.invoices.length} invoices from ${esc(data.business)}?`,()=>{state=data;save('Backup restored');});}catch(err){toast('Could not restore: '+err.message);}e.target.value='';}});
document.addEventListener('submit',e=>{if(e.target.id==='settings-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!d.business.trim()){toast('Enter a business name.');return;}state.business=d.business.trim();state.opening=Number(d.opening);state.reserve=Number(d.reserve);save('Business preferences saved');}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal();}});
function validateBackup(d){const bad=()=>{throw Error('Invalid or incompatible backup.');};const text=v=>typeof v==='string'&&v.length<=1000;const num=v=>Number.isSafeInteger(v)&&v>=0;const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(Date.parse(v));if(!d||d.version!==1||!text(d.business)||!Number.isSafeInteger(d.opening)||!num(d.reserve))bad();for(const k of ['students','invoices','payments','expenses','promises','scenarios','audit'])if(!Array.isArray(d[k])||d[k].length>50000)bad();for(const k of ['students','invoices','payments','expenses','promises','scenarios','audit']){if(d[k].some(x=>!x||!text(x.id)||!/^[-a-zA-Z0-9_]+$/.test(x.id))||new Set(d[k].map(x=>x.id)).size!==d[k].length)bad();}for(const s of d.students)if(!text(s.name)||!text(s.parent)||!text(s.batch)||!text(s.phone)||!num(s.fee)||s.fee<1||typeof s.archived!=='boolean')bad();for(const i of d.invoices)if(!d.students.some(s=>s.id===i.studentId)||!num(i.amount)||!date(i.due)||!/^\d{4}-(0[1-9]|1[0-2])$/.test(i.period))bad();for(const p of [...d.payments,...d.promises])if(!d.invoices.some(i=>i.id===p.invoiceId)||!num(p.amount)||p.amount<1||!date(p.date))bad();for(const p of d.payments)if(!text(p.method))bad();for(const i of d.invoices)if(paid(d,i.id)>i.amount)bad();for(const e of d.expenses)if(!text(e.title)||!text(e.category)||!num(e.amount)||!date(e.due)||typeof e.paid!=='boolean')bad();for(const s of d.scenarios)if(!text(s.name)||![30,60,90].includes(s.days)||!num(s.delay)||s.delay>30||!num(s.rate)||s.rate>100||!num(s.extra))bad();for(const a of d.audit)if(!text(a.text)||!text(a.time)||isNaN(Date.parse(a.time)))bad();}
try { validateBackup(state); for(const key of ['students','invoices','payments','expenses','promises','scenarios','audit']) if(state[key].some(x=>!/^[-a-zA-Z0-9_]+$/.test(x.id))) throw Error('Invalid identifier'); if (!localStorage.getItem(KEY)) localStorage.setItem(KEY,JSON.stringify(state)); } catch { state=seed(); toast('Saved data could not be loaded. Restore a valid backup in Settings.'); }
render();
